      sh.uniforms.uSwim = f.bend.swim; sh.uniforms.uSwim2 = f.bend.swim2;
      head += 'uniform vec4 uSwim; uniform vec4 uSwim2;\n';
      body += `{ float bw = 1.0 - smoothstep(uSwim2.y, uSwim2.x, position.x); bw *= bw;
                 transformed.z += sin(uSwim.x + position.x*uSwim.z)*uSwim.y*bw + uSwim2.z*bw; }\n`;
